program.compute:
options=read('/input/options')
from itertools import combinations
ids=[o['id'] for o in options]
opts_dict={o['id']:o for o in options}
result=[]
for k in range(goal['min_count'],goal['max_count']+1):
 for combo in combinations(ids,k):
  sel=list(combo)
  # Check requires closure
  closed=True
  if goal['closed_dependencies']:
   for cid in sel:
    for req in opts_dict[cid]['requires']:
     if req not in sel:
      closed=False
      break
    if not closed:
     break
  if not closed:
   continue
  # Check conflicts
  if goal['no_conflicts']:
   conflict_found=False
   for i in range(len(sel)):
    for j in range(i+1,len(sel)):
     if sel[j] in opts_dict[sel[i]]['conflicts'] or sel[i] in opts_dict[sel[j]]['conflicts']:
      conflict_found=True
      break
    if conflict_found:
     break
   if conflict_found:
    continue
  # Check cover tags
  tags_covered=[]
  for cid in sel:
   tags_covered+=opts_dict[cid]['tags']
  tags_covered=list(set(tags_covered))
  cover_tags=goal['cover'].get('tags',[])
  cover_ok=all(t in tags_covered for t in cover_tags)
  if not cover_ok:
   continue
  # Check sum_bounds cost max
  cost_sum=sum(opts_dict[cid]['cost'] for cid in sel)
  if 'cost' in goal['sum_bounds']:
   if 'max' in goal['sum_bounds']['cost']:
    if cost_sum>goal['sum_bounds']['cost']['max']:
     continue
   if 'min' in goal['sum_bounds']['cost']:
    if cost_sum<goal['sum_bounds']['cost']['min']:
     continue
  # Check unique fields
  unique_fields=goal.get('unique',[])
  unique_ok=True
  for uf in unique_fields:
   vals=[opts_dict[cid].get(uf) for cid in sel]
   if len(vals)!=len(set(vals)):
    unique_ok=False
    break
  if not unique_ok:
   continue
  # Check order_by ascending lex
  order_by=goal.get('order_by',[])
  if order_by:
   vals=[tuple(opts_dict[cid].get(f) for f in order_by) for cid in sel]
   if any(vals[i]>vals[i+1] for i in range(len(vals)-1)):
    continue
  # Check min_count max_count
  if len(sel)<goal['min_count'] or len(sel)>goal['max_count']:
   continue
  # Check valid
  if valid(sel):
   result=sel
   break
 if result:
  break

